 TvPosterRules.Picture small=TvPosterRules.parse("https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2935805973.webp@Referer=https://api.douban.com/");TvPosterRules.Picture high=TvPosterRules.highResolution(small);check(high.url.contains("/view/photo/l/public/"),"validated Douban large image variant");check(high.headers==small.headers,"preserve required image headers");TvPosterRules.Picture signed=TvPosterRules.parse(small.url+"?sign=abc");check(TvPosterRules.highResolution(signed)==signed,"never rewrite signed image URL");TvPosterRules.Picture other=TvPosterRules.parse("https://example.com/view/photo/s_ratio_poster/public/a.jpg");check(TvPosterRules.highResolution(other)==other,"do not rewrite unknown CDN");
 List<TvPosterRules.Picture> choices=TvPosterRules.candidates(TvPosterRules.parse("https://images.metahub.space/poster/small/tt21097264/img"));check(choices.size()==3,"two CDN alternatives and original retained");check(choices.get(0).url.equals("https://images.metahub.space/poster/medium/tt21097264/img"),"medium quality first");check(choices.get(1).url.equals("https://live.metahub.space/poster/medium/tt21097264/img"),"same IMDb and image kind on alternate CDN");check(TvPosterRules.candidates(TvPosterRules.parse("https://images.metahub.space/poster/small/tt21097264/img?token=private")).size()==1,"signed queries never rewritten");check(TvPosterRules.candidates(TvPosterRules.parse("https://images.metahub.space.evil.example/poster/small/tt21097264/img")).size()==1,"host matching exact");check(TvPosterRules.candidates(TvPosterRules.parse("https://live.metahub.space/background/medium/tt21097264/img")).get(1).url.contains("/background/medium/tt21097264/img"),"background must remain background");
